function loadtable(){datatable=$("#fee_payment").DataTable({processing:!0,serverSide:!0,filter:!0,responsive:!0,destroy:!0,ajax:{url:"/Home/FeesPayemtData",type:"POST",datatype:"json"},columnDefs:[{visible:!0,searchable:!0}],columns:[{data:"id",render:function(n,t,i,r){return r.row+r.settings._iDisplayStart+1}},{data:null,render:function(n){return n.termregistrations.studentsData.surName+" "+(n?.termregistrations.studentsData.otherName||"")+" "+n.termregistrations.studentsData.firstName}},{data:"termregistrations.studentsData.studentRegNo",autoWidth:!0},{data:"termlyFees.amount",autoWidth:!0},{data:"paid",autoWidth:!0},{data:"balance",autoWidth:!0},{data:null,render:function(n){return n.status=="Completed"?`<span class="badge h4 bg-success" title="Fees completed">
                        <i class="fas fa-check-double"></i> Completed
                        </span>`:`<label title="Part Payment" class="badge h3 bg-warning"><i class="fas fa-times-circle"></i> Part Payment</label>`}},{data:null,render:function(n){return n.termregistrations.sessionYear.name}},{data:null,render:function(n){return n.termregistrations.term}},{data:null,render:function(n){return n.termregistrations.schoolclasses.name+" - "+n.termregistrations.subClasses.name}},{data:null,render:function(n){return`
                        <div class="d-flex justify-content-center">
                         <button type="button" onclick="viewpaymentifo(this)" data-id="${n.id}" title="View payment details" class="btn btn-primary btn-sm waves-effect waves-light">
                         <i class="fa fa-eye"></i>
                         </button>
                            &nbsp;
                            <a target="_blank" class="btn btn-success btn-sm waves-effect waves-light" href="/ultilities/Fees-Payment-Invoice?id=${n.id}" style="cursor:pointer" title="Print receipt">
                                <i class="fas fa-print"></i>
                            </a> &nbsp;
                            <a onclick=FeesPaymentD("/api/FeesPaymentManager?id=${n.id}") class="btn btn-danger btn-sm waves-effect waves-light" href="#" style="cursor:pointer">
                                   <i class="fas fa-trash-alt"></i>
                               </a>
                        </div>
                    `}}]})}function FeesPaymentD(n){const t=Swal.mixin({customClass:{confirmButton:"btn btn-success",cancelButton:"btn btn-danger"},buttonsStyling:!1});t.fire({title:"Are you sure?",text:"You won't be able to recover this!",icon:"warning",showCancelButton:!0,confirmButtonText:"Yes, delete it!",cancelButtonText:"No, cancel!",reverseButtons:!0}).then(t=>{t.isConfirmed?$.ajax({type:"DELETE",url:n,success:function(n){$.unblockUI();n.success?(swal.fire("Deleted!",n.message,"success"),loadtable()):swal.fire("Deleted!",n.message,"error")},beforeSend:function(){blockcallback()},error:function(){$.unblockUI();Swal.fire({icon:"error",title:"Oops...",text:"Something went wrong!",footer:"Check internet connectivity!"})},complete:function(){$.unblockUI()}}):t.dismiss===Swal.DismissReason.cancel&&swal.fire("Cancelled","Fees Payment NOT Deleted!","error")})}function test(){$(".bs-example-modal-center").hide()}function viewpaymentifo(n){var i=$(n).data("id");let t=Number(i);if(t<1)return Swal.fire("Ooop!","Invalid data","erro");$.ajax({type:"GET",url:"/webapi/Veiwreceipt?id="+t,success:function(n){$.unblockUI();n&&(n!=null?($("#receipt").val(n.receiptNumber),$("#name").val(n.name),$("#studentreg").val(n.studentReg),$("#session").val(n.sessionyear),$("#term").val(n.term),$("#classes").val(n.classes),$("#fees").val(n.fees),$("#amount").val(n.amount),$("#balance").val(n.balance),$("#status").val(n.status),$("#description").val(n.description),$("#cash").val(n.cashier),$("#create").val(n.createdate),$(".bs-example-modal-center").show()):swal.fire("Ooop!","Unknow fees payment","error"))},beforeSend:function(){blockcallback()},error:function(){$.unblockUI();Swal.fire({icon:"error",title:"Oops...",text:"Something went wrong!",footer:"Check internet connectivity!"})},complete:function(){$.unblockUI()}})}function editPayment(){swal.fire("Ooop!","Sorry, payment made are none editable, kindly remove your payment and re-add for error corrections","success")}function blockcallback(){$.blockUI({message:'<div class="bs-spinner mt-4 mt-lg-0"><div class= "spinner-border text-success mr-2 mt-2" style="width: 10rem; height: 10rem;" role="status"><span class="sr-only">Loading...<\/span><\/div>',fadeIn:800,overlayCSS:{backgroundColor:"#1b2024",opacity:.8,zIndex:1200,cursor:"wait"},css:{border:0,color:"#fff",zIndex:1201,padding:0,backgroundColor:"transparent"},onBlock:function(){}})}var classbtn="",classfa="",ap="";$(document).ready(function(){loadtable()});